        <div class="hero-overlay"></div>
      </div>
      <div class="container hero-inner">
        <div class="hero-copy">
          <h1>HVAC Maintenance Plans in Loganville, GA</h1>
          <p class="hero-sub">Join over 300 local homeowners who trust Mid Lakes HVAC for year-round system tune-ups, priority service, and lower energy bills.</p>
          <div class="hero-actions">
            <a href="#contact" class="btn btn-primary">Sign Up for Our Maintenance Plan</a>
            <a href="tel:+16787760591" class="btn btn-ghost">Call to Enroll: (678) 776-0591</a>
          </div>
        </div>
