        <form class="quote-form" id="quote-form" novalidate>
          <h3>Get a Free Estimate</h3>
          <p class="form-intro">Fill out the form below and our team will reach out to schedule your service.</p>
          <div class="field-row">
            <div class="field">
              <label for="firstName">First name</label>
              <input type="text" id="firstName" name="firstName" placeholder="Jane" required />
            </div>
            <div class="field">
              <label for="lastName">Last name</label>
              <input type="text" id="lastName" name="lastName" placeholder="Doe" required />
            </div>
          </div>
          <div class="field-row">
            <div class="field">
              <label for="phone">Phone number</label>
