            </div>
            <div class="field">
              <label for="email">Email</label>
              <input type="email" id="email" name="email" placeholder="you@example.com" required />
            </div>
          </div>
          <div class="field">
            <label for="message">How can we help?</label>
            <textarea id="message" name="message" rows="3" placeholder="Tell us about your heating or cooling needs..."></textarea>
          </div>
          <button type="submit" class="btn btn-primary btn-block">Submit Request</button>
          <p class="form-success" id="form-success" role="status" hidden>Thanks! Your request has been received&mdash;we will call you shortly.</p>
        </form>
